const input = $json.body ?? $json;
const event = String(input.event_type ?? input.status ?? "").toLowerCase();
const dispatchStatus = String(input.dispatch_status ?? "").toLowerCase();
const responseText = String(input.response_text ?? input.message ?? input.body ?? "").trim();
const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const dispatchId = input.dispatch_id;
const dnc = input.dnc === true || input.do_not_contact === true;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];

const identityReady = Boolean(dealId && leadId && propertyId && dispatchId);
const blocked = dnc || blockers.length > 0;

let status = "receipt_pending";
let nextWorkflow = "WF-335";
let reason = "Provider event is pending or does not yet establish a seller response.";

if (!identityReady) {
  status = "incomplete";
  nextWorkflow = "WF-335";
  reason = "Deal, lead, property, or dispatch identity is incomplete.";
} else if (blocked) {
  status = "blocked";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent further seller communication.";
} else if (["response_received", "inbound_message", "seller_response"].includes(event) || Boolean(responseText)) {
  status = "seller_response_received";
  nextWorkflow = "WF-337";
  reason = "An inbound seller response was received and is ready for classification.";
} else if (["delivered", "delivery_success", "sent"].includes(event) || ["delivered", "sent"].includes(dispatchStatus)) {
  status = "delivered_awaiting_response";
  nextWorkflow = "WF-338";
  reason = "Offer was delivered; seller response window is now active.";
} else if (["failed", "delivery_failed", "bounced", "rejected"].includes(event) || ["failed", "bounced", "rejected"].includes(dispatchStatus)) {
  status = "delivery_failed";
  nextWorkflow = "WF-335";
  reason = "Provider reported failed delivery; dispatch recovery is required.";
} else if (["timeout", "response_timeout", "no_response"].includes(event)) {
  status = "response_timeout";
  nextWorkflow = "WF-338";
  reason = "Seller response window expired without a response.";
}

return [{
  json: {
    ...input,
    workflow_id: "WF-336",
    controller_status: status,
    delivery_status: event || dispatchStatus || "unknown",
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    dispatch_id: dispatchId,
    seller_response_text: responseText,
    next_workflow: nextWorkflow,
    reason,
    delivery_receipt_reconciled: ["delivered", "delivery_success", "sent"].includes(event) || ["delivered", "sent"].includes(dispatchStatus),
    seller_response_received: status === "seller_response_received",
    response_timeout: status === "response_timeout",
    requires_human_review: status === "blocked" || status === "delivery_failed",
    idempotency_key: input.idempotency_key ?? \`wf-336:\${dispatchId ?? "unknown"}:\${event || dispatchStatus || "unknown"}\`
  }
}];
